-- Initial inventory snapshot. Replaying the seed preserves changes.
create table if not exists public.pc_assets (
  id bigint generated by default as identity primary key,
  assegnatario text not null default '',
  nome_dispositivo text not null default '',
  area text not null default '',
  profilo text not null default '',
  tipologia text not null default '',
  marca text not null default '',
  modello text not null default '',
  anno text not null default '',
  numero_serie text not null default '',
  processore text not null default '',
  core_processore text not null default '',
  processori_logici text not null default '',
  ram text not null default '',
  gpu text not null default '',
  schermo text not null default '',
  archiviazione text not null default '',
  sistema_operativo text not null default '',
  versione_os text not null default '',
  data_installazione_os text not null default '',
  data_acquisto text not null default '',
  prezzo_acquisto text not null default '',
  venditore text not null default '',
  articolo_acquisto text not null default '',
  note text not null default '',
  foto text not null default '',
  is_archived boolean not null default false,
  updated_on date not null default ((now() at time zone 'Europe/Rome')::date),
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint pc_assets_profile check (profilo in ('Ufficio', 'Tecnico', 'Grafica', '3D avanzato')),
  constraint pc_assets_required check (btrim(assegnatario) <> '' and btrim(tipologia) <> '')
);

alter table public.pc_assets enable row level security;
revoke all on table public.pc_assets from public, anon, authenticated;
revoke all on sequence public.pc_assets_id_seq from public, anon, authenticated;
grant select, insert, update on public.pc_assets to service_role;
grant usage on sequence public.pc_assets_id_seq to service_role;

on conflict (id) do nothing;

select setval(
  'public.pc_assets_id_seq',
  greatest((select max(id) from public.pc_assets), (select last_value from public.pc_assets_id_seq)),
  true
);
